//
// Listing the app commands makes Tauri generate an `allow-<command>`
// permission for each (under permissions/autogenerated/) and deny any
// command a capability does not grant. The development commands
// (src/dev_commands.rs) exist only in builds with debug assertions, and so
// do the capabilities that grant them (capabilities/dev/): every other build
// neither registers the commands nor loads those capabilities.

const COMMANDS: &[&str] = &[
    // src/hid_commands.rs
    "list_devices",
    "open_device",
    "close_device",
    "send_receive",
    "send",
    "is_device_open",
    // src/dev_commands.rs
    "virtual_device_press_key",
    "virtual_device_release_key",
    "virtual_device_release_all",
    "virtual_device_hold_keys",
    "virtual_device_set_unlock_counter_max",
    "virtual_device_get_state",
    "virtual_device_reset",
    "dev_log",
    "dev_screenshot",
];

fn main() {
    println!("cargo:rerun-if-changed=capabilities");
    // Set by Cargo for the crate being built, so it follows the profile's
    // debug-assertions setting rather than the build script's own.
    let capabilities = if std::env::var_os("CARGO_CFG_DEBUG_ASSERTIONS").is_some() {
        "./capabilities/**/*.json"
    } else {
        "./capabilities/*.json"
    };
    let attributes = tauri_build::Attributes::new()
        .app_manifest(tauri_build::AppManifest::new().commands(COMMANDS))
        .capabilities_path_pattern(capabilities);
    if let Err(err) = tauri_build::try_build(attributes) {
        eprintln!("tauri-build failed: {err:#}");
        std::process::exit(1);
    }
}
